import React, { useState, useEffect } from 'react';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, updateDoc, arrayUnion, arrayRemove, deleteDoc } from "firebase/firestore";

function GroupDetailsScreen({ navigateTo, route }) {
    const groupId = route.params?.groupId;
    const user = auth.currentUser;

    const [group, setGroup] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isMember, setIsMember] = useState(false);
    const [joining, setJoining] = useState(false);
    
    const isCreator = group && user && user.uid === group.createdBy;


    // Function to fetch the specific group details
    const fetchGroupDetails = async () => {
        if (!groupId) {
            setError("No Group ID found.");
            setLoading(false);
            return;
        }

        try {
            const groupDocRef = doc(db, "groups", groupId);
            const docSnap = await getDoc(groupDocRef);

            if (docSnap.exists()) {
                const groupData = { id: docSnap.id, ...docSnap.data() };
                setGroup(groupData);
                
                if (groupData.members && groupData.members.includes(user.uid)) {
                    setIsMember(true);
                } else {
                    setIsMember(false);
                }
            } else {
                setError("Group not found.");
            }
        } catch (e) {
            console.error("Error fetching group details:", e);
            setError("Failed to load group details. Check Firestore rules.");
        } finally {
            setLoading(false);
        }
    };
    
    // Function to handle joining the group
    const handleJoinGroup = async () => {
        if (!user) return; 
        setJoining(true);
        setError(null);

        try {
            const groupDocRef = doc(db, "groups", groupId);
            await updateDoc(groupDocRef, {
                members: arrayUnion(user.uid)
            });

            setIsMember(true);
            alert("Success! You have joined the group.");
            navigateTo('GroupChat', { groupId: group.id });

        } catch (e) {
            console.error("Error joining group:", e);
            setError("Failed to join the group.");
        } finally {
            setJoining(false);
        }
    };

    // Function to handle a user leaving the group (self-removal)
    const handleLeaveGroup = async () => {
        if (!user || !isMember) return; 

        if (!window.confirm("Are you sure you want to leave this group?")) return;

        try {
            const groupDocRef = doc(db, "groups", groupId);
            await updateDoc(groupDocRef, {
                members: arrayRemove(user.uid)
            });

            alert("You have left the group.");
            navigateTo('Dashboard'); 

        } catch (e) {
            console.error("Error leaving group:", e);
            setError("Failed to leave the group.");
        }
    };
    
    // Function to handle a creator removing another member
    const handleRemoveMember = async (memberIdToRemove) => {
        if (!isCreator || memberIdToRemove === user.uid) return;

        if (!window.confirm(`Are you sure you want to remove ${memberIdToRemove.substring(0, 5)}...?`)) return;

        try {
            const groupDocRef = doc(db, "groups", groupId);
            await updateDoc(groupDocRef, {
                members: arrayRemove(memberIdToRemove)
            });

            alert(`Member ${memberIdToRemove.substring(0, 5)}... removed.`);
            fetchGroupDetails(); // Refresh the list

        } catch (e) {
            console.error("Error removing member:", e);
            setError("Failed to remove member.");
        }
    };
    
    // Function to handle group deletion (NEW FEATURE)
    const handleDeleteGroup = async () => {
        if (!isCreator || !window.confirm("WARNING: Are you sure you want to delete this group? This action cannot be undone.")) return;

        try {
            await deleteDoc(doc(db, "groups", groupId));

            alert("Group successfully deleted.");
            navigateTo('Dashboard'); 

        } catch (e) {
            console.error("Error deleting group:", e);
            setError("Failed to delete group. Check Firestore rules.");
        }
    };


    useEffect(() => {
        fetchGroupDetails();
    }, [groupId, user]);


    if (loading) return <p className="form-container" style={{ textAlign: 'center' }}>Loading Group Details...</p>;
    if (error) return <p className="form-container" style={{ color: 'red', textAlign: 'center' }}>Error: {error}</p>;
    if (!group) return <p className="form-container" style={{ textAlign: 'center' }}>Group data unavailable.</p>;


    return (
        <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto', textAlign: 'left' }}>
            <button onClick={() => navigateTo('Dashboard')} className="btn" style={{ marginBottom: '20px' }}>
                &larr; Back to Groups
            </button>
            
            <h1 style={{ borderBottom: '2px solid var(--color-primary)', paddingBottom: '10px' }}>
                {group.title}
            </h1>
            
            <p style={{ fontSize: '1.1em', lineHeight: '1.5' }}>{group.description}</p>
            
            <div className="card"> 
                <p><strong>Group ID:</strong> {groupId}</p>
                <p><strong>Created By:</strong> {isCreator ? "You" : group.createdBy.substring(0, 8) + '...'}</p>
                
                {/* Member List (Styled for Management) */}
                <h3 style={{ marginTop: '15px', color: 'var(--color-text)', borderBottom: '1px solid #eee' }}>Members ({group.members ? group.members.length : 0}):</h3>
                <ul>
                    {group.members && group.members.map(memberId => (
                        <li key={memberId} style={{ marginBottom: '5px' }}>
                            {memberId === user.uid ? "You" : memberId.substring(0, 8) + '...'} 
                            {memberId === group.createdBy && " (Creator)"}

                            {/* REMOVE BUTTON */}
                            {isCreator && memberId !== user.uid && (
                                <button
                                    onClick={() => handleRemoveMember(memberId)}
                                    className="btn btn-danger"
                                    style={{ padding: '4px 10px', fontSize: '12px', marginLeft: '10px' }}
                                >
                                    Remove
                                </button>
                            )}
                        </li>
                    ))}
                </ul>
                
                {/* Delete Group Button (Creator only) */}
                {isCreator && (
                    <button 
                        onClick={handleDeleteGroup} 
                        className="btn btn-danger" 
                        style={{ padding: '5px 10px', fontSize: '14px', marginTop: '15px' }}
                    >
                        Delete Group Permanently
                    </button>
                )}
            </div>
            
            <div style={{ marginTop: '30px', textAlign: 'center' }}>
                {isMember ? (
                    // Member actions: Chat or Leave
                    <>
                        <button
                            onClick={() => navigateTo('GroupChat', { groupId: group.id })}
                            className="btn btn-primary"
                            style={{ marginRight: '15px' }}
                        >
                            Go to Group Chat
                        </button>
                        
                        <button 
                            onClick={handleLeaveGroup}
                            className="btn btn-danger"
                        >
                            Leave Group
                        </button>
                    </>
                ) : (
                    // Non-member action: Join Group
                    <button 
                        onClick={handleJoinGroup}
                        disabled={joining}
                        className="btn btn-primary"
                    >
                        {joining ? "Joining..." : "Join Group"}
                    </button>
                )}
                {error && <p style={{ color: 'red', marginTop: '10px' }}>{error}</p>}
            </div>
        </div>
    );
}

export default GroupDetailsScreen;