// src/screens/CreateGroupScreen.js
import React, { useState } from 'react';
import { db, auth } from '../firebaseConfig';
import { collection, addDoc } from "firebase/firestore"; 

function CreateGroupScreen({ navigateTo }) {
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(false);
    
    const user = auth.currentUser;
    const isUserLoggedIn = user && user.uid;

    const handleCreateGroup = async () => {
        if (!isUserLoggedIn) {
            setError("You must be logged in to create a group.");
            return;
        }
        if (!title || !description) {
            setError("Title and description are required.");
            return;
        }

        setError(null);
        setLoading(true);

        const newGroupData = {
            title: title,
            description: description,
            createdBy: user.uid,
            members: [user.uid],
            createdAt: new Date().toISOString()
        };

        try {
            await addDoc(collection(db, "groups"), newGroupData);

            console.log("Group created successfully!");
            navigateTo('Dashboard'); 

        } catch (e) {
            console.error("Group creation error:", e.message);
            setError("Error creating group. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="form-container" style={{maxWidth: '500px'}}> {/* <-- USING FORM CONTAINER CLASS */}
            <h2>Create a New Idea Group</h2>
            <p>Start a project, hackathon team, or study group!</p>
            
            <label>Group Title</label>
            <input
                type="text"
                placeholder="e.g., AI Chatbot for Students"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="input-field" // <-- USING INPUT CLASS
            />
            
            <label>Description (Goals, Skills Needed, etc.)</label>
            <textarea
                placeholder="Describe your idea and the kind of teammates you need."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows="4"
                className="input-field" // <-- USING INPUT CLASS
            />
            
            {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

            <button
                onClick={handleCreateGroup}
                disabled={loading}
                className="btn btn-primary" // <-- PRIMARY BUTTON
                style={{ width: '100%', marginTop: '15px' }}
            >
                {loading ? "Creating..." : "Create Group"}
            </button>
            <button
                onClick={() => navigateTo('Dashboard')}
                className="btn" // <-- DEFAULT BUTTON
                style={{ width: '100%', marginTop: '10px', backgroundColor: '#e0e0e0', color: 'black' }}
            >
                Cancel
            </button>
        </div>
    );
}

export default CreateGroupScreen;