import React, { useState, useEffect } from 'react';
import { db, auth } from '../firebaseConfig';
import { collection, getDocs, doc, getDoc } from "firebase/firestore";
import { getMatchScores } from '../utils/matchingLogic'; // Assume logic is imported

function MatchScreen({ navigateTo }) {
    const [matches, setMatches] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const currentUser = auth.currentUser;
    const [userGroups, setUserGroups] = useState([]); 

    // Fetch user's created groups to enable inviting
    useEffect(() => {
        const fetchUserGroups = async () => {
            if (!currentUser) return;
            try {
                const groupsSnapshot = await getDocs(collection(db, "groups"));
                const createdGroups = groupsSnapshot.docs
                    .filter(doc => doc.data().createdBy === currentUser.uid)
                    .map(doc => ({ id: doc.id, title: doc.data().title }));
                setUserGroups(createdGroups);
            } catch (e) {
                console.error("Failed to fetch user groups for inviting:", e);
            }
        };
        fetchUserGroups();
    }, [currentUser]);


    useEffect(() => {
        const runMatching = async () => {
            if (!currentUser) {
                setError("User not logged in.");
                setLoading(false);
                return;
            }

            try {
                // 1. Fetch current user's profile
                const userDoc = await getDoc(doc(db, "users", currentUser.uid));
                if (!userDoc.exists() || !userDoc.data().skills) {
                    setError("Please complete your profile (skills/interests) to run matching!");
                    setLoading(false);
                    return;
                }
                const currentUserProfile = { id: currentUser.uid, ...userDoc.data() };

                // 2. Fetch all other user profiles
                const usersSnapshot = await getDocs(collection(db, "users"));
                const allCandidateProfiles = usersSnapshot.docs
                    .map(doc => ({ id: doc.id, ...doc.data() }));

                // 3. Run the matching algorithm
                const calculatedScores = getMatchScores(currentUserProfile, allCandidateProfiles);
                
                setMatches(calculatedScores);

            } catch (e) {
                console.error("Matching Error:", e);
                setError("Failed to run matching. Check console.");
            } finally {
                setLoading(false);
            }
        };

        runMatching();
    }, [currentUser]);

    const handleInvite = (candidateId, groupTitle) => {
        // MVP: This simulates sending an invitation. 
        alert(`Invitation sent to ${candidateId.substring(0, 5)}... to join group "${groupTitle}"!`);
    };


    return (
        <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
            <h2>🤝 Teammate Recommendations</h2>
            <p>We found {matches.length} potential teammates based on your profile:</p>

            <button onClick={() => navigateTo('Dashboard')} className="btn" style={{ marginBottom: '20px' }}>
                &larr; Back to Dashboard
            </button>
            
            {loading && <p>Calculating match scores...</p>}
            {error && <p className="card" style={{ color: 'red' }}>Error: {error}</p>}
            
            {matches.map((match, index) => (
                <div key={match.candidateId} className="card" style={{ borderLeft: '5px solid var(--color-primary)', cursor: 'default' }}>
                    
                    <h3 style={{ color: 'var(--color-primary)' }}>Match Score: {Math.round(match.totalScore * 100)}%</h3>
                    <p>Candidate User ID: {match.candidateId.substring(0, 8)}...</p>
                    <p style={{ fontSize: '0.9em', color: '#666' }}>
                        (Contribution: Skill ({Math.round(match.details.skillScore * 100)}%), 
                        Interest ({Math.round(match.details.interestScore * 100)}%), 
                        Availability ({Math.round(match.details.availabilityScore * 100)}%))
                    </p>
                    
                    <div style={{ marginTop: '15px', borderTop: '1px solid #eee', paddingTop: '10px' }}>
                        
                        {/* VIEW PROFILE BUTTON - Now navigates to the viewer screen */}
                        <button 
                            onClick={() => navigateTo('ProfileViewer', { candidateId: match.candidateId })}
                            className="btn" 
                            style={{ marginRight: '10px', backgroundColor: '#e9e9e9', color: 'black' }}
                        >
                            View Profile
                        </button>
                        
                        {/* INVITE TEAMMATE BUTTON - Actionable link */}
                        {userGroups.length > 0 ? (
                            <button 
                                onClick={() => handleInvite(match.candidateId, userGroups[0].title)} 
                                className="btn btn-primary"
                            >
                                Invite to {userGroups[0].title}
                            </button>
                        ) : (
                            // Actionable link to create group
                            <button
                                onClick={() => navigateTo('CreateGroup')} 
                                className="btn btn-secondary"
                                style={{ fontSize: '12px' }}
                            >
                                Create a group to invite!
                            </button>
                        )}
                    </div>
                </div>
            ))}
        </div>
    );
}

export default MatchScreen;