import React, { useState, useEffect } from 'react';
import { db } from '../firebaseConfig';
import { doc, setDoc, getDoc } from "firebase/firestore"; 
import { auth } from '../firebaseConfig'; 

function CompleteProfileScreen({ navigateTo }) {
    const user = auth.currentUser;
    const [skills, setSkills] = useState('');
    const [interests, setInterests] = useState('');
    const [availabilityHours, setAvailabilityHours] = useState('');
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);

    // Fetch existing profile data if editing
    useEffect(() => {
        if (!user) return;
        const fetchProfile = async () => {
            const docRef = doc(db, "users", user.uid);
            const docSnap = await getDoc(docRef);
            
            if (docSnap.exists()) {
                const data = docSnap.data();
                setSkills(Array.isArray(data.skills) ? data.skills.join(', ') : data.skills || '');
                setInterests(Array.isArray(data.interests) ? data.interests.join(', ') : data.interests || '');
                setAvailabilityHours(data.availabilityHours || '');
                setIsEditing(true);
            }
        };
        fetchProfile();
    }, [user]);

    const handleProfileSubmit = async () => {
        if (!user || !skills || !interests || !availabilityHours) {
            setError("All fields are required.");
            return;
        }

        setError(null);
        setLoading(true);
        
        const profileData = {
            skills: skills.split(',').map(s => s.trim()).filter(s => s.length > 0), 
            interests: interests.split(',').map(i => i.trim()).filter(i => i.length > 0),
            availabilityHours: parseInt(availabilityHours),
            lastUpdated: new Date().toISOString(),
            ...(isEditing ? {} : { createdAt: new Date().toISOString() }) 
        };

        try {
            await setDoc(doc(db, "users", user.uid), profileData, { merge: true });

            alert("Profile saved successfully!");
            navigateTo('Dashboard'); 

        } catch (e) {
            console.error("Profile submission error:", e.message);
            setError("Error saving profile. Check console for details.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="form-container" style={{maxWidth: '500px'}}>
            <h2>{isEditing ? "Edit Your Profile" : "Complete Your Profile"}</h2>
            <p>Tell us about your skills and availability so we can find your ideal teammates!</p>
            
            <label>Skills (Comma separated: e.g., React, Python, Figma)</label>
            <input
                type="text"
                value={skills}
                onChange={(e) => setSkills(e.target.value)}
                className="input-field" 
            />
            
            <label>Interests (Comma separated: e.g., AI, Fintech, Gaming)</label>
            <input
                type="text"
                value={interests}
                onChange={(e) => setInterests(e.target.value)}
                className="input-field" 
            />
            
            <label>Weekly Availability (Hours)</label>
            <input
                type="number"
                value={availabilityHours}
                onChange={(e) => setAvailabilityHours(e.target.value)}
                min="1"
                max="50"
                className="input-field" 
            />
            
            {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

            <button
                onClick={handleProfileSubmit}
                disabled={loading}
                className="btn btn-primary" 
                style={{ width: '100%', marginTop: '15px' }}
            >
                {loading ? "Saving Profile..." : (isEditing ? "Save Changes" : "Complete & Go to Dashboard")}
            </button>
            
            {isEditing && (
                <button
                    onClick={() => navigateTo('Dashboard')}
                    className="btn"
                    style={{ width: '100%', marginTop: '10px', backgroundColor: '#e0e0e0', color: 'black' }}
                >
                    Cancel
                </button>
            )}
        </div>
    );
}

export default CompleteProfileScreen;